import{_ as s,o as a,c as n,X as l}from"./chunks/framework.6bc268d3.js";const e="/blog/assets/RPlogo.0f31fb7c.svg",m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"markdown/RaspberryPi/index.md","filePath":"markdown/RaspberryPi/index.md","lastUpdated":null}'),p={name:"markdown/RaspberryPi/index.md"},o=l('<h1 id="" tabindex="-1"><img src="'+e+`" alt="树莓派Logo"> <a class="header-anchor" href="#" aria-label="Permalink to &quot;![树莓派Logo](./RPlogo.svg)&quot;">​</a></h1><p>近期购入一台 4U8G 的树莓派5，用于搭建一个 Home Assistant 的容器环境，以及搭建一个 NAS 系统。我想通过这篇文章记录下整个过程。这其中用到了 docker等相关技术，我会记录下这个过程。方便日后查阅。</p><h2 id="前期准备" tabindex="-1">前期准备 <a class="header-anchor" href="#前期准备" aria-label="Permalink to &quot;前期准备&quot;">​</a></h2><ul><li>树莓派5（4U8G）</li><li>64G 的 SD 卡（读卡器）</li><li>树莓派HDMI线</li><li>一根短网线</li><li>一台电脑</li><li>WI-FI环境</li></ul><h2 id="树莓派自动发送-ip-地址到邮箱" tabindex="-1">树莓派自动发送 IP 地址到邮箱 <a class="header-anchor" href="#树莓派自动发送-ip-地址到邮箱" aria-label="Permalink to &quot;树莓派自动发送 IP 地址到邮箱&quot;">​</a></h2><p>配置树莓派在连接 WiFi 时，自动获取其内网和公网 IP，并通过 Postfix 邮件服务发送到指定邮箱。</p><h3 id="准备工作" tabindex="-1">准备工作 <a class="header-anchor" href="#准备工作" aria-label="Permalink to &quot;准备工作&quot;">​</a></h3><ol><li><p><strong>安装必要工具</strong></p><ul><li><p>安装 <code>mailutils</code> 和 <code>postfix</code>：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">apt</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">update</span></span>
<span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">apt</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">install</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">mailutils</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">postfix</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">-y</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div></li><li><p>在 Postfix 配置中选择 <strong>Internet Site</strong>，并设置系统主机名为树莓派的主机名，例如 <code>dg-pi</code>。</p></li></ul></li><li><p><strong>配置 Postfix</strong> 按照以下步骤配置 Postfix 使用 QQ 邮箱的 SMTP 中继：</p><ul><li>编辑 <code>/etc/postfix/main.cf</code>：</li></ul></li></ol><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">nano</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">/etc/postfix/main.cf</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>添加以下内容：</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">relayhost = [smtp.qq.com]:587</span></span>
<span class="line"><span style="color:#A6ACCD;">smtp_sasl_auth_enable = yes</span></span>
<span class="line"><span style="color:#A6ACCD;">smtp_sasl_password_maps = hash:/etc/postfix/sasl_passwd</span></span>
<span class="line"><span style="color:#A6ACCD;">smtp_sasl_security_options = noanonymous</span></span>
<span class="line"><span style="color:#A6ACCD;">smtp_use_tls = yes</span></span>
<span class="line"><span style="color:#A6ACCD;">smtp_tls_CAfile = /etc/ssl/certs/ca-certificates.crt</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><ul><li>创建 <code>/etc/postfix/sasl_passwd</code> 文件：</li></ul><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">nano</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">/etc/postfix/sasl_passwd</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>内容如下：</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">[smtp.qq.com]:587 247328581@qq.com:your_smtp_authorization_code</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>替换 <code>your_smtp_authorization_code</code> 为您的 QQ 邮箱授权码。</p><ul><li>更新配置并设置权限：</li></ul><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">postmap</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">/etc/postfix/sasl_passwd</span></span>
<span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">chmod</span><span style="color:#A6ACCD;"> </span><span style="color:#F78C6C;">600</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">/etc/postfix/sasl_passwd</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">/etc/postfix/sasl_passwd.db</span></span>
<span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">systemctl</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">restart</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">postfix</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ol start="3"><li><strong>验证邮件发送功能</strong> 测试 Postfix 是否能够发送邮件：</li></ol><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#82AAFF;">echo</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Test Email</span><span style="color:#89DDFF;">&quot;</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">|</span><span style="color:#A6ACCD;"> </span><span style="color:#FFCB6B;">mail</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">-s</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Test Subject</span><span style="color:#89DDFF;">&quot;</span><span style="color:#A6ACCD;"> </span><span style="color:#F78C6C;">247328581</span><span style="color:#C3E88D;">@qq.com</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="自动发送-ip-脚本" tabindex="-1">自动发送 IP 脚本 <a class="header-anchor" href="#自动发送-ip-脚本" aria-label="Permalink to &quot;自动发送 IP 脚本&quot;">​</a></h3><p>创建一个脚本，在树莓派连接 WiFi 时获取 IP 并发送到邮箱。</p><p>1.创建脚本文件 创建 /usr/local/bin/send_ip.sh 文件：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">nano</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">/usr/local/bin/send_ip.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>内容如下：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#676E95;font-style:italic;">#!/bin/bash</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 获取内网 IP</span></span>
<span class="line"><span style="color:#A6ACCD;">INTERNAL_IP</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">$(</span><span style="color:#FFCB6B;">hostname</span><span style="color:#C3E88D;"> -I </span><span style="color:#89DDFF;">|</span><span style="color:#C3E88D;"> </span><span style="color:#FFCB6B;">awk</span><span style="color:#C3E88D;"> </span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">{print $1}</span><span style="color:#89DDFF;">&#39;)</span></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 获取公网 IP</span></span>
<span class="line"><span style="color:#A6ACCD;">EXTERNAL_IP</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">$(</span><span style="color:#FFCB6B;">curl</span><span style="color:#C3E88D;"> -s https://api64.ipify.org</span><span style="color:#89DDFF;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 邮件内容</span></span>
<span class="line"><span style="color:#A6ACCD;">SUBJECT</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">树莓派已连接 WiFi</span><span style="color:#89DDFF;">&quot;</span></span>
<span class="line"><span style="color:#A6ACCD;">MESSAGE</span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">树莓派当前的 IP 地址：\\n内网 IP：</span><span style="color:#A6ACCD;">$INTERNAL_IP</span><span style="color:#C3E88D;">\\n公网 IP：</span><span style="color:#A6ACCD;">$EXTERNAL_IP</span><span style="color:#89DDFF;">&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 调试日志</span></span>
<span class="line"><span style="color:#82AAFF;">echo</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Internal IP: </span><span style="color:#A6ACCD;">$INTERNAL_IP</span><span style="color:#89DDFF;">&quot;</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&gt;&gt;</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">/tmp/send_ip_debug.log</span></span>
<span class="line"><span style="color:#82AAFF;">echo</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">External IP: </span><span style="color:#A6ACCD;">$EXTERNAL_IP</span><span style="color:#89DDFF;">&quot;</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&gt;&gt;</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">/tmp/send_ip_debug.log</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 发送邮件</span></span>
<span class="line"><span style="color:#82AAFF;">echo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">-e</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&quot;</span><span style="color:#A6ACCD;">$MESSAGE</span><span style="color:#89DDFF;">&quot;</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">|</span><span style="color:#A6ACCD;"> </span><span style="color:#FFCB6B;">mail</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">-s</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&quot;</span><span style="color:#A6ACCD;">$SUBJECT</span><span style="color:#89DDFF;">&quot;</span><span style="color:#A6ACCD;"> </span><span style="color:#F78C6C;">247328581</span><span style="color:#C3E88D;">@qq.com</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 检查邮件发送状态</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">if</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">[</span><span style="color:#A6ACCD;"> $? </span><span style="color:#89DDFF;">-eq</span><span style="color:#A6ACCD;"> </span><span style="color:#F78C6C;">0</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">];</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;font-style:italic;">then</span></span>
<span class="line"><span style="color:#A6ACCD;">    </span><span style="color:#82AAFF;">echo</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Mail sent successfully</span><span style="color:#89DDFF;">&quot;</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&gt;&gt;</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">/tmp/send_ip_debug.log</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">else</span></span>
<span class="line"><span style="color:#A6ACCD;">    </span><span style="color:#82AAFF;">echo</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Mail failed to send</span><span style="color:#89DDFF;">&quot;</span><span style="color:#A6ACCD;"> </span><span style="color:#89DDFF;">&gt;&gt;</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">/tmp/send_ip_debug.log</span></span>
<span class="line"><span style="color:#89DDFF;font-style:italic;">fi</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br></div></div><p>2.设置脚本权限</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">chmod</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">+x</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">/usr/local/bin/send_ip.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>3.测试脚本 手动运行脚本验证功能：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">/usr/local/bin/send_ip.sh</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>检查 /tmp/send_ip_debug.log 或目标邮箱确认是否收到邮件。</p><h3 id="配置自动运行" tabindex="-1">配置自动运行 <a class="header-anchor" href="#配置自动运行" aria-label="Permalink to &quot;配置自动运行&quot;">​</a></h3><p>使用 systemd 配置树莓派连接 WiFi 后自动运行脚本。 1.创建 systemd 服务文件 创建 /etc/systemd/system/send_ip.service 文件：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">nano</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">/etc/systemd/system/send_ip.service</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>内容如下：</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">[Unit]</span></span>
<span class="line"><span style="color:#A6ACCD;">Description=Send Raspberry Pi IP Address</span></span>
<span class="line"><span style="color:#A6ACCD;">After=network-online.target</span></span>
<span class="line"><span style="color:#A6ACCD;"></span></span>
<span class="line"><span style="color:#A6ACCD;">[Service]</span></span>
<span class="line"><span style="color:#A6ACCD;">ExecStart=/usr/local/bin/send_ip.sh</span></span>
<span class="line"><span style="color:#A6ACCD;">Type=oneshot</span></span>
<span class="line"><span style="color:#A6ACCD;"></span></span>
<span class="line"><span style="color:#A6ACCD;">[Install]</span></span>
<span class="line"><span style="color:#A6ACCD;">WantedBy=multi-user.target</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>2.启用服务</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">systemctl</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">enable</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">send_ip.service</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>3.手动启动服务测试 运行以下命令检查脚本是否正常运行：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">systemctl</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">start</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">send_ip.service</span></span>
<span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">systemctl</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">status</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">send_ip.service</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>4.重启设备验证<br> 重启树莓派：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">reboot</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>检查邮箱是否收到 IP 地址邮件。</p><h2 id="树莓派通过-postfix-使用-qq-邮箱发送邮件" tabindex="-1">树莓派通过 Postfix 使用 QQ 邮箱发送邮件 <a class="header-anchor" href="#树莓派通过-postfix-使用-qq-邮箱发送邮件" aria-label="Permalink to &quot;树莓派通过 Postfix 使用 QQ 邮箱发送邮件&quot;">​</a></h2><p>本文记录在树莓派上配置 Postfix 通过 QQ 邮箱 SMTP 中继发送邮件的过程，并解决 SPF 验证失败和配置重复的问题。</p><hr><h3 id="问题描述" tabindex="-1">问题描述 <a class="header-anchor" href="#问题描述" aria-label="Permalink to &quot;问题描述&quot;">​</a></h3><ol><li><p><strong>SPF 验证失败</strong> 错误信息：<code>550 SPF check failed</code> 邮件服务器拒绝了发件人地址。</p></li><li><p><strong>Postfix 配置重复</strong> 错误信息：<code>overriding earlier entry: relayhost=[smtp.qq.com]:587</code></p></li></ol><p>配置文件中多次定义了 <code>relayhost</code>。</p><hr><h3 id="解决方案" tabindex="-1">解决方案 <a class="header-anchor" href="#解决方案" aria-label="Permalink to &quot;解决方案&quot;">​</a></h3><h4 id="_1-配置-postfix-使用-qq-邮箱的-smtp-服务" tabindex="-1">1. 配置 Postfix 使用 QQ 邮箱的 SMTP 服务 <a class="header-anchor" href="#_1-配置-postfix-使用-qq-邮箱的-smtp-服务" aria-label="Permalink to &quot;1. 配置 Postfix 使用 QQ 邮箱的 SMTP 服务&quot;">​</a></h4><ol><li><strong>编辑配置文件</strong> 打开 <code>/etc/postfix/main.cf</code>：</li></ol><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">nano</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">/etc/postfix/main.cf</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>添加以下内容：</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">relayhost = [smtp.qq.com]:587</span></span>
<span class="line"><span style="color:#A6ACCD;">smtp_sasl_auth_enable = yes</span></span>
<span class="line"><span style="color:#A6ACCD;">smtp_sasl_password_maps = hash:/etc/postfix/sasl_passwd</span></span>
<span class="line"><span style="color:#A6ACCD;">smtp_sasl_security_options = noanonymous</span></span>
<span class="line"><span style="color:#A6ACCD;">smtp_use_tls = yes</span></span>
<span class="line"><span style="color:#A6ACCD;">smtp_tls_CAfile = /etc/ssl/certs/ca-certificates.crt</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>2.设置 SMTP 验证</p><p>创建 /etc/postfix/sasl_passwd 文件：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">nano</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">/etc/postfix/sasl_passwd</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>内容如下：</p><div class="language-txt line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#A6ACCD;">[smtp.qq.com]:587 247328581@qq.com:your_smtp_authorization_code</span></span>
<span class="line"><span style="color:#A6ACCD;"># 将 your_smtp_authorization_code 替换为 QQ 邮箱的授权码。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>3.更新配置并设置权限</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">postmap</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">/etc/postfix/sasl_passwd</span></span>
<span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">chmod</span><span style="color:#A6ACCD;"> </span><span style="color:#F78C6C;">600</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">/etc/postfix/sasl_passwd</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">/etc/postfix/sasl_passwd.db</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>4.重启 Postfix</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">systemctl</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">restart</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">postfix</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>5.验证配置 执行以下命令检查配置是否正确：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">postfix</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">check</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>6.重启 Postfix 服务</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">systemctl</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">restart</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">postfix</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="danger custom-block"><p class="custom-block-title">注意事项</p><p>确保 <code>/etc/postfix/sasl_passwd</code> 和 <code>/etc/postfix/sasl_passwd.db</code> 权限正确：</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">sudo</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">chmod</span><span style="color:#A6ACCD;"> </span><span style="color:#F78C6C;">600</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">/etc/postfix/sasl_passwd</span><span style="color:#A6ACCD;"> </span><span style="color:#C3E88D;">/etc/postfix/sasl_passwd.db</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></div><h2 id="树莓派安装docker" tabindex="-1">树莓派安装docker <a class="header-anchor" href="#树莓派安装docker" aria-label="Permalink to &quot;树莓派安装docker&quot;">​</a></h2><h2 id="安装homeassistant镜像" tabindex="-1">安装HomeAssistant镜像 <a class="header-anchor" href="#安装homeassistant镜像" aria-label="Permalink to &quot;安装HomeAssistant镜像&quot;">​</a></h2><h2 id="家庭模型、智能家居位置处理、灯光图渲染" tabindex="-1">家庭模型、智能家居位置处理、灯光图渲染 <a class="header-anchor" href="#家庭模型、智能家居位置处理、灯光图渲染" aria-label="Permalink to &quot;家庭模型、智能家居位置处理、灯光图渲染&quot;">​</a></h2><h2 id="ps-制作灯光电器控制图" tabindex="-1">ps 制作灯光电器控制图 <a class="header-anchor" href="#ps-制作灯光电器控制图" aria-label="Permalink to &quot;ps 制作灯光电器控制图&quot;">​</a></h2><h2 id="调测ha代码与控制图匹配制作" tabindex="-1">调测HA代码与控制图匹配制作 <a class="header-anchor" href="#调测ha代码与控制图匹配制作" aria-label="Permalink to &quot;调测HA代码与控制图匹配制作&quot;">​</a></h2><h2 id="修改homeassistant皮肤管理" tabindex="-1">修改HomeAssistant皮肤管理 <a class="header-anchor" href="#修改homeassistant皮肤管理" aria-label="Permalink to &quot;修改HomeAssistant皮肤管理&quot;">​</a></h2>`,76),t=[o];function r(c,i,d,C,y,u){return a(),n("div",null,t)}const D=s(p,[["render",r]]);export{m as __pageData,D as default};
